syntax = "proto2";
message M {
  option (f) = "a" "b";
  optional int32 x = 1 [(g) = "c" "d"];
  extensions 1 to 2 [(h) = "e" "f"];
  oneof o {
    option (i) = "g" "h";
    int32 y = 2;
  }
}

syntax = "proto2";
service S {
  option (f) = "a" "b";
  rpc M (A) returns (B) { option (g) = "c" "d"; }
}

syntax = "proto2";
message M {
  optional string s = 1 [default = "a" "b", json_name = "j" "k"];
}

syntax = "proto2";
message M {
  optional bytes b = 1 [default = "a\001" "b\"\\'"];
  optional bytes c = 2 [default = "\xff" "\x7f" "\t\r\n" "~ "];
}
